pub fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    if n <= 1 {
        return numbers;
    }

    // For n >= 2, the result length is 2*n - 1.
    let mut result = Vec::with_capacity(2 * n - 1);

    // Push first element, then (delimiter, element) for the rest.
    result.push(numbers[0]);
    for &x in numbers.iter().skip(1) {
        result.push(delimiter);
        result.push(x);
    }

    result
}